function componentsPage(params){
 const view=['kit','states','api'].includes(params.get('view'))?params.get('view'):'kit';
 const tabs=[['kit','Компоненты'],['states','Состояния страниц'],['api','Контракт API']];
 const head=`<div class="page-top"><div class="crumb"><a href="#home">Главная</a><span>/</span><span>Неделя 2</span></div><p class="eyebrow">Frontend A + Frontend B</p><h1>Один интерфейс.<br>Общие правила.</h1><p class="lead">Библиотека компонентов и состояний для публичных страниц и будущих кабинетов.</p><span class="chip">Версия 0.2 · на согласование команде</span></div><nav class="kit-tabs" aria-label="Разделы библиотеки">${tabs.map(([id,label])=>`<a href="#components?view=${id}"${view===id?' aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
 if(view==='states')return head+`<section class="panel"><div class="section-head"><div><p class="eyebrow">Проверка в контексте</p><h2>У каждого состояния есть выход</h2></div></div><p>Откройте макет настоящего каталога. Фильтры остаются на странице, а повтор загрузки возвращает выбранную подборку.</p><div class="state-grid">${['authors','jobs'].map(type=>`<article class="state-preview"><h3>${type==='authors'?'Каталог авторов':'Каталог заданий'}</h3><p>${type==='authors'?'Карточки авторов, площадка и цена.':'Предложения компаний, площадка и бюджет.'}</p><div class="state-links">${[['ready','Данные'],['loading','Загрузка'],['empty','Пустой результат'],['error','Ошибка']].map(([state,label])=>UI.button({label,href:'#'+type+(state==='ready'?'':'?demo='+state),variant:'secondary'})).join('')}</div></article>`).join('')}</div></section><section class="panel"><h2>Поведение страницы</h2><div class="rules-grid"><div><strong>Загрузка</strong><p>Текстовый статус и неподвижные по размеру заготовки карточек.</p></div><div><strong>Пустая подборка</strong><p>Объяснение и действие для сброса фильтров.</p></div><div><strong>Ошибка</strong><p>Понятное сообщение, повтор и сохранённые параметры поиска.</p></div><div><strong>Нет статистики</strong><p>В будущем API — null. В интерфейсе — «Пока нет данных», не ноль.</p></div></div></section>`;
 if(view==='api')return head+`<section class="panel"><h2>Предложение для Backend A</h2>${UI.alert({tone:'info',title:'Контракт ещё не согласован',message:'Здесь описаны необходимые данные и поведение. Реального подключения к серверу пока нет.'})}<div class="api-table"><table><thead><tr><th>Экран</th><th>Предлагаемый метод</th><th>Что требуется</th></tr></thead><tbody><tr><td>Каталог авторов</td><td><code>GET /api/v1/authors</code></td><td>Автор, канал, услуга, цена, доступность, статистика</td></tr><tr><td>Профиль автора</td><td><code>GET /api/v1/authors/{id}</code></td><td>Публичный профиль, каналы, услуги, работы</td></tr><tr><td>Каталог заданий</td><td><code>GET /api/v1/advertising-tasks</code></td><td>Компания, формат, бюджет, сроки, статус</td></tr><tr><td>Карточка задания</td><td><code>GET /api/v1/advertising-tasks/{id}</code></td><td>Описание, условия, правки, права, материалы</td></tr></tbody></table></div><div class="actions">${UI.button({label:'Описание контракта',href:'api-contract.txt',variant:'secondary'})}${UI.button({label:'Пример ответа JSON',href:'api-example.json',variant:'secondary'})}</div></section><div class="grid two"><section class="panel"><h2>Фильтры и списки</h2><p>Площадка, формат, тема, город, цена или бюджет, доступность. Страницы по 20 записей, максимум 50 — предложение для согласования.</p><p>Сортировка с устойчивым порядком. Смена фильтра возвращает на первую страницу.</p><p class="muted">В текущем макете работают площадка и бюджет. Остальные фильтры описаны для будущей реализации.</p></section><section class="panel"><h2>Единый формат ошибок</h2><pre><code>{
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "Проверьте поля",
    "fields": {
      "price_max_minor": "Введите сумму от 0"
    },
    "request_id": "demo-request-001"
  }
}</code></pre><p>Ошибки полей показываются рядом с полями; общий сбой — сообщением с повтором.</p></section></div><section class="panel"><h2>Нужно решение команды</h2><ul><li>Backend A: имена методов и полей, обязательность, права, фильтры и пагинация.</li><li>Frontend B: интерфейсы компонентов, состояния форм и подтверждения.</li><li>Продакт-менеджер: критерии доступности автора и правила скрытия закрытых заданий.</li></ul></section>`;
 return head+`<div class="kit-summary"><div><strong>5</strong><span>семейств компонентов</span></div><div><strong>4</strong><span>состояния каталога</span></div><div><strong>2</strong><span>frontend-разработчика</span></div><p>Компоненты вынесены в общий файл и используются в каталогах прототипа.</p></div><div class="kit-grid"><section class="panel"><p class="eyebrow">Действия</p><h2>Кнопки</h2><p class="muted">Один главный призыв на шаг. Второстепенные действия визуально спокойнее.</p><div class="button-samples">${UI.button({label:'Найти автора',href:'#authors'})}${UI.button({label:'Посмотреть задания',href:'#jobs',variant:'secondary'})}${UI.button({label:'Недоступно',disabled:true})}${UI.button({label:'Сохраняем…',loading:true})}</div><p class="field-hint">Ожидание блокирует повторное действие. Состояние доступно скринридеру.</p></section><section class="panel"><p class="eyebrow">Обратная связь</p><h2>Сообщения</h2>${UI.alert({title:'Не удалось сохранить',message:'Введённые данные остаются в форме. Повторите попытку позже.'})}${UI.alert({tone:'success',title:'Изменения сохранены',message:'Пример успешного сообщения. Реального сохранения нет.'})}</section><section class="panel"><p class="eyebrow">Ввод и проверка</p><h2>Поля формы</h2><p class="muted">Попробуйте оставить название пустым или ввести отрицательную цену.</p><form id="kit-form" class="form-grid" novalidate>${UI.field({id:'kit-name',label:'Название услуги',value:'Обзор кафе',required:true,hint:'От 3 до 80 символов.'})}${UI.field({id:'kit-price',label:'Цена от, ₽',kind:'number',value:'3000',min:1,required:true,hint:'Целое число от 1 до 1 000 000.'})}${UI.field({id:'kit-platform',label:'Площадка',kind:'select',value:'vk',options:[{value:'vk',label:'ВКонтакте'},{value:'telegram',label:'Telegram'}]})}<div class="actions">${UI.button({label:'Проверить форму',type:'submit'})}${UI.button({label:'Очистить поля',id:'kit-reset',variant:'secondary'})}</div></form><div id="kit-feedback" class="feedback" aria-live="polite"></div></section><section class="panel"><p class="eyebrow">Подтверждение</p><h2>Действия с последствиями</h2><p>Перед очисткой заполненных полей показываем, что произойдёт. Отмена и Escape сохраняют введённые значения.</p><div class="dialog-preview"><span class="chip">Пример окна</span><h3>Очистить заполненные поля?</h3><p>Название и цена будут удалены из демонстрационной формы.</p><div class="chips"><span class="chip">Отмена</span><span class="chip">Очистить</span></div></div><p class="muted">Откройте окно кнопкой «Очистить поля» в форме. Фокус остаётся внутри окна. После отмены он возвращается к кнопке, после очистки — к первому полю.</p></section></div><section><div class="section-head"><div><p class="eyebrow">Контент</p><h2>Общие карточки</h2></div><a class="text-link" href="#components?view=states">Состояния страниц</a></div><div class="grid two">${UI.authorCard(authors[0])}${UI.jobCard(jobs[1])}</div></section><section class="panel kit-bottom"><h2>Основа оформления</h2><div class="token-row"><span><i style="background:#183d32"></i>Основной текст</span><span><i style="background:#d9f886"></i>Акцент</span><span><i style="background:#e5ddfa"></i>Подложка</span><span><i style="background:#f7faf7"></i>Фон</span></div><p>Основной текст — 16 px. Интерактивные элементы — от 48 px по высоте. Сетка: одна колонка на телефоне, две или три на широком экране.</p></section>`;
}
function bindComponents(params){
 const form=document.getElementById('kit-form');if(!form)return;
 const name=document.getElementById('kit-name'),price=document.getElementById('kit-price'),feedback=document.getElementById('kit-feedback');
 for(const input of [name,price])input.addEventListener('input',()=>{UI.fieldError(input,'');feedback.innerHTML=''});
 form.onsubmit=e=>{e.preventDefault();const errors=validateServiceDraft(name.value,price.value);UI.fieldError(name,errors.name||'');UI.fieldError(price,errors.price||'');if(errors.name||errors.price){feedback.innerHTML=UI.alert({title:'Проверьте поля',message:'Исправьте отмеченные значения и повторите проверку.'});(errors.name?name:price).focus();return}feedback.innerHTML=UI.alert({tone:'success',title:'Форма заполнена правильно',message:'Это локальная проверка. Данные на сервер не отправлялись.'})};
 document.getElementById('kit-reset').onclick=async()=>{const accepted=await UI.confirm({title:'Очистить заполненные поля?',message:'Название и цена будут удалены из демонстрационной формы. Отмена сохранит текущие значения.',confirmLabel:'Очистить',danger:true});if(!accepted){feedback.innerHTML=UI.alert({tone:'info',title:'Очистка отменена',message:'Введённые значения сохранены.'});return}name.value='';price.value='';UI.fieldError(name,'');UI.fieldError(price,'');feedback.innerHTML=UI.alert({tone:'info',title:'Поля очищены',message:'Можно заполнить новый пример.'});name.focus()};
}
function validateServiceDraft(name,price){const errors={};if(name.trim().length<3||name.trim().length>80)errors.name='Введите название от 3 до 80 символов.';if(!/^\d+$/.test(price.trim())||Number(price)<1||Number(price)>1000000)errors.price='Введите целую сумму от 1 до 1 000 000 ₽.';return errors}
